import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { uniqueTags } from '../src/tags.js';

const mode = process.argv[2];
if (mode === 'case') {
  const examples = [
    [['JS', 'Node', 'js', 'NODE', 'css'], ['JS', 'Node', 'css']],
    [['js', 'JS', 'Js', 'jS'], ['js']],
    [['B', 'a', 'b', 'A', 'C', 'c'], ['B', 'a', 'C']],
    [['', '', 'x', 'X'], ['', 'x']],
    [[' A', 'a', ' A', 'A', 'a '], [' A', 'a', 'a ']],
    [['Foo-Bar', 'foo-bar', 'FOO_BAR', 'foo_bar', '123', '123'], ['Foo-Bar', 'FOO_BAR', '123']],
    [['École', 'éCOLE', 'Ω', 'ω'], ['École', 'Ω']],
  ];
  for (const [input, expected] of examples) {
    const before = [...input];
    assert.deepEqual(uniqueTags(input), expected);
    assert.deepEqual(input, before, 'must not mutate input');
  }
  const input = [];
  const expected = [];
  for (let i = 0; i < 25000; i++) {
    const first = i % 2 ? `tag-${i}` : `TAG-${i}`;
    input.push(first);
    expected.push(first);
    if (i > 0) input.push(expected[i - 1].toLowerCase());
  }
  input.push(...expected.map(t => t.toUpperCase()));
  assert.deepEqual(uniqueTags(input), expected);
} else if (mode === 'regression') {
  for (const [input, expected] of [
    [[], []],
    [['node', 'js', 'node', 'css', 'js'], ['node', 'js', 'css']],
    [['z', 'b', 'a'], ['z', 'b', 'a']],
    [['one', 'one', 'one'], ['one']],
    [['', ' ', '', '  ', ' '], ['', ' ', '  ']],
  ]) {
    const before = [...input];
    assert.deepEqual(uniqueTags(input), expected);
    assert.deepEqual(input, before);
  }
  const input = Array.from({length: 100000}, (_, i) => `tag-${i}`);
  assert.deepEqual(uniqueTags([...input, ...input]), input);
} else if (mode === 'speed') {
  const unique = Array.from({length: 200000}, (_, i) => `Tag-${i}`);
  const mixed = [...unique, ...unique.map(t => t.toUpperCase())];
  const repeated = Array.from({length: 400000}, (_, i) => `tag-${i % 100}`);
  uniqueTags(unique.slice(0, 2000));
  const times = [];
  for (let round = 0; round < 3; round++) {
    let total = 0;
    for (const input of [unique, mixed, repeated]) {
      const start = performance.now();
      const result = uniqueTags(input);
      const elapsed = performance.now() - start;
      assert.ok(Array.isArray(result));
      assert.ok(elapsed < 750, `processing ${input.length} tags took ${elapsed.toFixed(1)}ms (limit 750ms)`);
      total += elapsed;
    }
    times.push(total);
  }
  times.sort((a, b) => a - b);
  console.log(times[1]);
} else {
  throw new Error('unknown check mode');
}
